/**
 * Story 1.2: Frontend Navigation Shell
 * Epic 1: Project Foundation & Application Shell
 *
 * Automation Expansion — Edge Cases & Boundary Conditions (E2E level)
 * Generated by *automate after ATDD (navigation-shell.spec.ts) went GREEN.
 * Focus: scenarios NOT covered by the original ATDD suite — real-browser CSS
 * breakpoint behavior (the ATDD component tests only assert Tailwind class names
 * in jsdom, which does not apply real CSS), the `lg:` boundary itself, a
 * genuinely unknown deep-linked route in a real browser, and click-driven
 * active-state updates end to end.
 *
 * Acceptance Criteria covered:
 *   AC1 — NavigationRail visible on desktop (real computed CSS, not just class names)
 *   AC2 — NavigationBar visible on mobile (real computed CSS, not just class names)
 *   AC5 — Unknown route renders a graceful not-found view, nav stays visible (E2E, real browser)
 *   AC6 — Active nav item updates after a real click-driven navigation
 */

import { test, expect } from '@playwright/test';

// ─────────────────────────────────────────────────────────────────────────────
// AC1/AC2 — Real-browser CSS breakpoint behavior (Tailwind `lg: 1024px`)
// ─────────────────────────────────────────────────────────────────────────────

test.describe('AC1/AC2 — Desktop viewport shows NavigationRail, hides NavigationBar', () => {
  test('[P1] should render only the rail container as visible at a desktop viewport (1280px)', async ({ page }) => {
    // GIVEN: a desktop-sized viewport (well above the lg: 1024px breakpoint)
    await page.setViewportSize({ width: 1280, height: 800 });

    // WHEN: the app loads at /clientes
    await page.goto('/clientes');

    // THEN: the rail container is visible and the bar container is not (real computed CSS)
    await expect(page.getByTestId('nav-rail-container')).toBeVisible();
    await expect(page.getByTestId('nav-bar-container')).toBeHidden();
  });
});

test.describe('AC1/AC2 — Mobile viewport shows NavigationBar, hides NavigationRail', () => {
  test('[P1] should render only the bar container as visible at a mobile viewport (375px)', async ({ page }) => {
    // GIVEN: a mobile-sized viewport (well below the lg: 1024px breakpoint)
    await page.setViewportSize({ width: 375, height: 667 });

    // WHEN: the app loads at /clientes
    await page.goto('/clientes');

    // THEN: the bar container is visible and the rail container is not (real computed CSS)
    await expect(page.getByTestId('nav-bar-container')).toBeVisible();
    await expect(page.getByTestId('nav-rail-container')).toBeHidden();
  });
});

test.describe('AC1/AC2 — Boundary condition at the exact lg: breakpoint (1024px)', () => {
  test('[P2] should render the rail as visible right at the 1024px breakpoint boundary', async ({ page }) => {
    // GIVEN: a viewport exactly at Tailwind's lg: breakpoint (min-width: 1024px is inclusive)
    await page.setViewportSize({ width: 1024, height: 800 });

    // WHEN: the app loads at /clientes
    await page.goto('/clientes');

    // THEN: the rail (desktop) container is the one shown at the boundary itself
    await expect(page.getByTestId('nav-rail-container')).toBeVisible();
    await expect(page.getByTestId('nav-bar-container')).toBeHidden();
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// AC5 — Unknown route in a real browser (not just the jsdom component test)
// ─────────────────────────────────────────────────────────────────────────────

test.describe('AC5 — Deep-linking to a genuinely unknown route shows a graceful not-found view', () => {
  test('[P1] should display the not-found message and keep navigation visible for an unknown top-level route', async ({ page }) => {
    // GIVEN: a fixed desktop viewport, so the rail (not the bar) is the deterministic
    // nav container to assert on regardless of which Playwright project runs this
    await page.setViewportSize({ width: 1280, height: 800 });
    const runtimeErrors: string[] = [];
    page.on('pageerror', (err) => runtimeErrors.push(err.message));

    // WHEN: the user requests a route that does not exist anywhere in the app
    await page.goto('/ruta-que-no-existe');

    // THEN: the graceful Spanish not-found message renders (no blank page)
    await expect(page.getByText(/página no encontrada/i)).toBeVisible();

    // AND: the navigation shell remains mounted
    await expect(page.getByTestId('nav-rail-container')).toBeVisible();

    // AND: no unhandled JS error occurred
    expect(runtimeErrors).toHaveLength(0);
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// AC6 — Active nav item updates after a real click-driven navigation
// ─────────────────────────────────────────────────────────────────────────────

test.describe('AC6 — Active nav item updates end-to-end after clicking a rail item', () => {
  test('[P2] should mark Contactos active and Clientes inactive after clicking Contactos from Clientes', async ({ page }) => {
    // GIVEN: the user is on /clientes with the desktop rail visible
    await page.setViewportSize({ width: 1280, height: 800 });
    await page.goto('/clientes');
    const contactosResponse = page.waitForURL('**/contactos');

    // WHEN: the user clicks the "Contactos" rail item
    await page.getByRole('button', { name: /contactos/i }).click();
    await contactosResponse;

    // THEN: the Contactos item is marked as the current page and Clientes is not
    await expect(page.getByRole('button', { name: /contactos/i })).toHaveAttribute('aria-current', 'page');
    await expect(page.getByRole('button', { name: /clientes/i })).not.toHaveAttribute('aria-current', 'page');
  });
});
